-- ==============================================================================
-- AGRISENTRY & N8N WORKFLOWS SUPABASE DATABASE SCHEMA
-- Idempotent setup for:
--   1. assessments (Crop diagnosis & micro-climate risk timelines)
--   2. assessment_feedback (Outcomes & verification collected via Workflow 1)
--   3. evaluation_runs (Periodic evaluation benchmarks generated by Workflow 2)
--   4. risk_rule_versions (Controlled proposed rule updates from Workflow 2)
-- ==============================================================================

-- 1. ASSESSMENTS TABLE
CREATE TABLE IF NOT EXISTS public.assessments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ DEFAULT now() NOT NULL,
  crop_type TEXT,
  growth_stage TEXT,
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  status TEXT DEFAULT 'completed',
  diagnosis JSONB,
  weather JSONB,
  risk_assessment JSONB,
  advisory JSONB,
  model_name TEXT DEFAULT 'gemini-2.5-flash-agri',
  model_version TEXT DEFAULT 'v1.2.0',
  risk_rule_version TEXT DEFAULT 'v1.0.0-icar',
  error_codes JSONB DEFAULT '[]'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_assessments_created_at ON public.assessments(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_assessments_status ON public.assessments(status);

-- 2. ASSESSMENT FEEDBACK TABLE (n8n Workflow 1 target)
CREATE TABLE IF NOT EXISTS public.assessment_feedback (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  assessment_id UUID REFERENCES public.assessments(id) ON DELETE CASCADE,
  label_source TEXT NOT NULL,
  verification_status TEXT,
  observed_crop_type TEXT,
  confirmed_disease TEXT,
  disease_observed TEXT,
  outcome_status TEXT,
  days_after_assessment INTEGER,
  farmer_found_advisory_helpful BOOLEAN,
  notes TEXT,
  payload_hash TEXT,
  evaluation_eligible BOOLEAN DEFAULT true,
  evaluation_blockers TEXT[],
  evaluation_case JSONB,
  created_at TIMESTAMPTZ DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_feedback_assessment_id ON public.assessment_feedback(assessment_id);
CREATE INDEX IF NOT EXISTS idx_feedback_payload_hash ON public.assessment_feedback(assessment_id, payload_hash);
CREATE INDEX IF NOT EXISTS idx_feedback_created_at ON public.assessment_feedback(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_feedback_label_source ON public.assessment_feedback(label_source);

-- 3. EVALUATION RUNS TABLE (n8n Workflow 2 output)
CREATE TABLE IF NOT EXISTS public.evaluation_runs (
  id BIGSERIAL PRIMARY KEY,
  run_key TEXT UNIQUE NOT NULL,
  period_start TIMESTAMPTZ,
  period_end TIMESTAMPTZ,
  dataset_size INTEGER DEFAULT 0,
  expert_verified_size INTEGER DEFAULT 0,
  metrics JSONB,
  model_version TEXT,
  risk_rule_version TEXT,
  limitations JSONB,
  evaluation_status TEXT DEFAULT 'completed',
  workflow_execution_id TEXT,
  created_at TIMESTAMPTZ DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_eval_runs_created_at ON public.evaluation_runs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_eval_runs_run_key ON public.evaluation_runs(run_key);

-- 4. RISK RULE VERSIONS TABLE (n8n Workflow 2 proposals)
CREATE TABLE IF NOT EXISTS public.risk_rule_versions (
  id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  version TEXT UNIQUE NOT NULL,
  status TEXT DEFAULT 'proposed',
  parent_version TEXT,
  change_type TEXT,
  title TEXT,
  description TEXT,
  evidence JSONB,
  source_references JSONB,
  requires_expert_review BOOLEAN DEFAULT true,
  regression_test_status TEXT DEFAULT 'required_not_run',
  regression_test_result JSONB,
  evaluation_run_key TEXT,
  activated_at TIMESTAMPTZ,
  created_by TEXT DEFAULT 'agrisentry-evaluation-workflow',
  created_at TIMESTAMPTZ DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_rule_versions_status ON public.risk_rule_versions(status);
CREATE INDEX IF NOT EXISTS idx_rule_versions_version ON public.risk_rule_versions(version);

-- 5. ENABLE ROW LEVEL SECURITY & OPEN PERMISSIVE POLICIES
ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assessment_feedback ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.evaluation_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.risk_rule_versions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read assessments" ON public.assessments;
CREATE POLICY "Public read assessments" ON public.assessments FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public insert assessments" ON public.assessments;
CREATE POLICY "Public insert assessments" ON public.assessments FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public update assessments" ON public.assessments;
CREATE POLICY "Public update assessments" ON public.assessments FOR UPDATE USING (true);

DROP POLICY IF EXISTS "Public read feedback" ON public.assessment_feedback;
CREATE POLICY "Public read feedback" ON public.assessment_feedback FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public insert feedback" ON public.assessment_feedback;
CREATE POLICY "Public insert feedback" ON public.assessment_feedback FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public read eval runs" ON public.evaluation_runs;
CREATE POLICY "Public read eval runs" ON public.evaluation_runs FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public insert eval runs" ON public.evaluation_runs;
CREATE POLICY "Public insert eval runs" ON public.evaluation_runs FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public read rule versions" ON public.risk_rule_versions;
CREATE POLICY "Public read rule versions" ON public.risk_rule_versions FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public insert rule versions" ON public.risk_rule_versions;
CREATE POLICY "Public insert rule versions" ON public.risk_rule_versions FOR INSERT WITH CHECK (true);

-- 6. SEED INITIAL RISK RULE VERSION (So Workflow 2 has a baseline version)
INSERT INTO public.risk_rule_versions (id, version, status, title, description, created_by)
VALUES (
  'rule-icar-v1',
  'v1.0.0-icar',
  'active',
  'ICAR Standard Horticultural Disease Rules',
  'Baseline biological rules for fungal sporulation thresholds and leaf-wetness risk modeling.',
  'agrisentry-system'
)
ON CONFLICT (version) DO NOTHING;
